issue_context.body:
There are a few e2e sig-network tests  that are using e2essh, limiting the number of environments where they can run.

https://github.com/kubernetes/kubernetes/blob/0fd10997dfee0f9ec2c413004bf93d310d76c84b/test/e2e/network/service.go#L2592-L2594

some of them can be easily replaced executing the commands on a pod, per example the ones that execute commands on kube-proxy can be done with:

```
func execKubeProxyCommand(cs clientset.Interface, cmd string) error {
	namespace := "kube-system"
	pods, err := cs.CoreV1().Pods(namespace).List(context.TODO(), metav1.ListOptions{})
	if err != nil || len(pods.Items) == 0 {
		framework.Logf("failed to list kube-proxy pods in namespace: %s", namespace)
		return
	}
	for _, pod := range pods.Items {
		if strings.Contains(pod.Name, "kube-proxy") {
			stdout, err := framework.RunHostCmd(namespace, pod.Name, cmd)
			if err != nil {
				framework.Logf("Failed to exec command on node %s: %v", pod.Spec.NodeName, err)
				return err
			}
			framework.Logf("command outoput on node %s: %s", pod.Spec.NodeName, stdout)
		}
	}
        return nil
}
```
